@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

class Reviewer {
  + reviewerID : int
}

Person "1" -- "1" ResearchInstitution : worksFor
Person "1" -- "0..*" AuthorPosition : author
AuthorPosition "1" -- "1" ScientificArticle : belongsTo
Person "1" -- "0..*" Reviewer : reviewer
Reviewer "1" -- "1" PeerReviewedPaper : reviews
ScientificArticle --|> PeerReviewedPaper
ScientificArticle --|> TechnicalReport
TechnicalReport "*" -- "1" ResearchInstitution : publishedBy
PeerReviewedPaper "*" -- "1" Journal : publishedIn
Publisher "1" -- "1..*" Journal : publishes
ResearchInstitution "1" -- "0..*" Journal : subscribesTo

@enduml

